import {focusedRuleFields} from "./data-layer-focused-schema-property-ui.js";
import type {ComposedFocusedSectionContext} from "./data-layer-composed-schema-workspace-focused-sections.js";
import {renderSharedConditionTree} from "./data-layer-shared-condition-tree-editor.js";

const labeled=(dom:Document,text:string,control:HTMLElement):HTMLLabelElement=>{const label=dom.createElement("label");label.append(text,control);return label;};
const button=(dom:Document,text:string,run:()=>void):HTMLButtonElement=>{const control=dom.createElement("button");control.type="button";control.textContent=text;control.addEventListener("click",run);return control;};
const numericFields=new Set(["minimum","maximum","minItems","maxItems"]);
const clone=<T>(value:T):T=>structuredClone(value);

function renderRuleEditor(row:HTMLElement,rule:Record<string,unknown>,index:number,context:ComposedFocusedSectionContext):void {
  const {dom}=context,editor=dom.createElement("fieldset");editor.setAttribute("aria-label",`Edit rule ${String(rule.id??index)}`);
  for(const field of focusedRuleFields(String(rule.kind??"custom"))){
    if(field==="condition"){
      const condition=dom.createElement("div");renderSharedConditionTree(condition,{dom,...(rule.condition?{condition:rule.condition as any}:{}),properties:()=>context.model.rows.map(({path,effective})=>({id:effective.definitionId??path,name:path,...(effective.type?{type:effective.type}: {})})),id:(kind)=>`${kind}:${crypto.randomUUID()}`,onChange:(next)=>{if(next)rule.condition=next as unknown as Record<string,unknown>;else delete rule.condition;context.render();}});editor.append(labeled(dom,"Shared condition tree",condition));continue;
    }
    const control=field==="severity"?dom.createElement("select"):dom.createElement("input");control.name=`editRule${field[0]!.toUpperCase()+field.slice(1)}`;if(control instanceof HTMLSelectElement)control.append(new Option("error","error"),new Option("warning","warning"));else if(numericFields.has(field))control.type="number";control.value=String(rule[field]??"");control.addEventListener("input",()=>{const draft=context.getDraft();if(!draft)return;const next=clone(draft.rules[index] as Record<string,unknown>);next[field]=control.value===""?undefined:numericFields.has(field)?Number(control.value):control.value;draft.rules[index]=next;});editor.append(labeled(dom,field,control));
  }
  row.append(editor);
}

export function renderComposedFocusedRules(host:HTMLElement,context:ComposedFocusedSectionContext):void {
  const {dom}=context,draft=context.getDraft();if(!draft)return;const list=dom.createElement("div");list.setAttribute("aria-label","Stable rule inventory");const localIds=new Set((context.row.local.rules??[]).map((rule)=>String(rule.id??"")));const displayedById=new Map<string,Record<string,unknown>>();for(const rule of context.row.effective.rules??[])displayedById.set(String(rule.id??`rule:${displayedById.size}`),rule as Record<string,unknown>);for(const rule of draft.rules)displayedById.set(String(rule.id??`rule:${displayedById.size}`),rule);[...displayedById.values()].forEach((rule,index)=>{const row=dom.createElement("article"),summary=dom.createElement("p"),id=String(rule.id??`rule-${index}`),localIndex=draft.rules.findIndex((candidate)=>String(candidate.id??"")===id),local=localIndex>=0||localIds.has(id)||context.overriddenRuleIds.has(id),removed=context.removedRuleIds.has(id);row.dataset.ruleId=id;row.dataset.ownership=local?"local":"inherited";summary.textContent=`${String(rule.name??rule.kind??"rule")} · ${String(rule.kind??"custom")} · ${String(rule.severity??"error")} · ${String(rule.message??"No issue message")} · ${local?"local":"inherited"}${removed?" · Removed":""}`;row.append(summary,button(dom,"View",()=>{row.dataset.ruleMode="view";const detail=dom.createElement("p");detail.textContent=`Rule ${id} · definition ${JSON.stringify(rule)} · effective ${rule.enabled===false?"disabled":"enabled"} · source ${local?"local":"inherited"}`;row.append(detail);}));if(local&&!removed)row.append(button(dom,"Edit",()=>{row.dataset.ruleMode="edit";renderRuleEditor(row,rule,localIndex,context);}),button(dom,"Remove local",()=>{context.restoredRuleIds.delete(id);context.removedRuleIds.add(id);context.render();}));else if(local)row.append(button(dom,"Restore",()=>{context.removedRuleIds.delete(id);context.restoredRuleIds.add(id);context.render();}));else row.append(button(dom,"Override here",()=>context.overrideRule(id)),button(dom,"Open source",()=>{row.dataset.ruleMode="source";const detail=dom.createElement("p");detail.textContent=`Source rule ${id} · inherited definition is read-only.`;row.append(detail);}));list.append(row);});
  const addPanel=dom.createElement("fieldset"),kind=dom.createElement("select"),fields=dom.createElement("div");kind.name="ruleKind";kind.append(new Option("Choose rule kind",""),...["pattern","range","cardinality","condition","custom"].map((entry)=>new Option(entry,entry)));
  const renderFields=()=>{fields.replaceChildren();if(!kind.value)return;const names=focusedRuleFields(kind.value).filter((name)=>name!=="condition");for(const name of names){if(name==="reusableRuleId"){const search=dom.createElement("input");search.type="search";search.name="reusableRuleSearch";search.placeholder="Search reusable rules by name";const reusable=dom.createElement("select");reusable.name="reusableRuleId";reusable.setAttribute("aria-label","Reusable rule name");reusable.append(new Option("No reusable rule",""),...draft.rules.filter(({reusableRuleId},index,array)=>reusableRuleId&&array.findIndex((candidate)=>candidate.reusableRuleId===reusableRuleId)===index).map((candidate)=>new Option(String(candidate.name??candidate.reusableRuleId),String(candidate.reusableRuleId))));fields.append(labeled(dom,"Search reusable rules",search),labeled(dom,"Reusable rule",reusable));continue;}const control=name==="severity"?dom.createElement("select"):dom.createElement("input");control.name=`newRule${name}`;if(control instanceof HTMLSelectElement)control.append(new Option("error","error"),new Option("warning","warning"));else if(numericFields.has(name))control.type="number";fields.append(labeled(dom,name,control));}};
  kind.addEventListener("change",renderFields);renderFields();addPanel.append(labeled(dom,"Rule kind",kind),fields,button(dom,"Add rule",()=>{const rule:Record<string,unknown>={id:`rule:${crypto.randomUUID()}`,kind:kind.value,severity:"error",message:""};for(const control of Array.from(fields.querySelectorAll<HTMLInputElement|HTMLSelectElement>("input,select")))if(control.value)rule[control.name.replace(/^newRule/,"").replace(/^./,(letter)=>letter.toLowerCase())]=numericFields.has(control.name.replace(/^newRule/,""))?Number(control.value):control.value;const reusable=fields.querySelector<HTMLSelectElement>("[name=\"reusableRuleId\"]");if(reusable?.value)rule.reusableRuleId=reusable.value;draft.rules=[...draft.rules,rule];context.render();}));host.append(list,addPanel);
}
